1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.repository.OwnerRepository;
5	
6	/**
7	 * Per-city capacity rules shared between the create-time guard {@link EnsureOwnerCityCapacity} and
8	 * the read-time {@code capacityWarning} surfaced on the owner response.
9	 *
10	 * <p>A city holds at most {@value #CITY_OWNER_LIMIT} owners; once it already contains that many a new
11	 * owner is rejected. The warning flags the run-up to that limit: {@code true} once a city holds
12	 * between {@value #CITY_WARNING_THRESHOLD} and {@code CITY_OWNER_LIMIT - 1} owners (inclusive).
13	 * Cities are compared case-insensitively, matching how owners are counted for the hard limit.
14	 */
15	public final class OwnerCityCapacity {
16	
17	    /** Maximum number of owners permitted in a single city. */
18	    public static final int CITY_OWNER_LIMIT = 50;
19	
20	    /** A city holding this many owners (up to, but not including, the limit) raises the warning. */
21	    public static final int CITY_WARNING_THRESHOLD = 40;
22	
23	    private OwnerCityCapacity() {
24	    }
25	
26	    /** Whether {@code city} already holds {@link #CITY_OWNER_LIMIT} or more owners. */
27	    public static boolean isAtCapacity(OwnerRepository ownerRepository, String city) {
28	        return countOwnersInCity(ownerRepository, city) >= CITY_OWNER_LIMIT;
29	    }
30	
31	    /**
32	     * Whether {@code city} is approaching the capacity limit: {@code true} when it already holds
33	     * between {@value #CITY_WARNING_THRESHOLD} and {@code CITY_OWNER_LIMIT - 1} owners (inclusive).
34	     * At or beyond the hard limit this is {@code false} — the city is at capacity, not merely
35	     * approaching it.
36	     */
37	    public static boolean isWarning(OwnerRepository ownerRepository, String city) {
38	        int count = countOwnersInCity(ownerRepository, city);
39	        return count >= CITY_WARNING_THRESHOLD && count < CITY_OWNER_LIMIT;
40	    }
41	
42	    private static int countOwnersInCity(OwnerRepository ownerRepository, String city) {
43	        int count = 0;
44	        for (Owner existing : ownerRepository.findAll()) {
45	            if (city == null ? existing.getCity() == null : city.equalsIgnoreCase(existing.getCity())) {
46	                count++;
47	            }
48	        }
49	        return count;
50	    }
51	}
