1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	import java.util.Map;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
23	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
24	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
25	    @Mapping(target = "initials", expression = "java(initials(owner))")
26	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
27	    @Mapping(target = "locality", expression = "java(locality(owner))")
28	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
29	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
30	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
31	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
32	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
33	    @Mapping(target = "bulkSignupWarning", ignore = true)
34	    @Mapping(target = "capacityWarning", ignore = true)
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    /**
38	     * The owner's canonical self link, derived at read time as {@code '/api/owners/'} followed by
39	     * the owner's id. Null when the owner or its id is absent, so the field is simply omitted then.
40	     */
41	    default String selfLink(Owner owner) {
42	        if (owner == null || owner.getId() == null) {
43	            return null;
44	        }
45	        return "/api/owners/" + owner.getId();
46	    }
47	
48	    /**
49	     * The owner's fiscal year, derived at read time and formatted {@code FY<YY>}. It references the
50	     * {@code memberId}: the two FY digits sit between the REGION prefix and the HASH8 segment, so this
51	     * reads them straight back out (2026-07-01 registration -> {@code memberId} 'NSW27...' -> {@code
52	     * FY27}). Owners predating the unified {@code memberId} (e.g. seed data) fall back to the
53	     * (business-day-adjusted) {@code registrationDate}, where the fiscal year starts on 1 July.
54	     * Null when neither source is available, so the field is simply omitted then.
55	     */
56	    default String fiscalYear(Owner owner) {
57	        if (owner == null) {
58	            return null;
59	        }
60	        String fromMember = fiscalYearFromMemberId(owner.getMemberId());
61	        if (fromMember != null) {
62	            return fromMember;
63	        }
64	        if (owner.getRegistrationDate() == null) {
65	            return null;
66	        }
67	        return String.format("FY%02d", fiscalYearOf(owner.getRegistrationDate()) % 100);
68	    }
69	
70	    /**
71	     * Reads the {@code FY<YY>} value out of the {@code memberId}: the two digits immediately after the
72	     * leading REGION letters. Null when the {@code memberId} is absent or does not have two digits in
73	     * that position. Kept {@code private static} so MapStruct does not treat it as a property mapping.
74	     */
75	    private static String fiscalYearFromMemberId(String memberId) {
76	        if (memberId == null) {
77	            return null;
78	        }
79	        int i = 0;
80	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
81	            i++;
82	        }
83	        if (i == 0 || memberId.length() < i + 2) {
84	            return null;
85	        }
86	        String yy = memberId.substring(i, i + 2);
87	        return yy.matches("[0-9]{2}") ? "FY" + yy : null;
88	    }
89	
90	    /**
91	     * The fiscal year a date falls in, as a full calendar year. The fiscal year starts on 1 July, so
92	     * a date in July or later belongs to the next calendar year and an earlier date to the current
93	     * calendar year. Kept {@code private static} so MapStruct does not treat it as a property mapping.
94	     */
95	    private static int fiscalYearOf(java.time.LocalDate date) {
96	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
97	    }
98	
99	    /**
100	     * The owner's age band, derived at read time from {@code birthDate} relative to the
101	     * {@code registrationDate}: {@code MINOR} under 18, {@code ADULT} from 18 to 64 and
102	     * {@code SENIOR} at 65 or older. Null when the owner or its {@code birthDate} (or the
103	     * {@code registrationDate} it is measured against) is absent, so the field is simply
104	     * omitted for owners without a birth date.
105	     */
106	    default String ageBand(Owner owner) {
107	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
108	            return null;
109	        }
110	        int years = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
111	        if (years < 18) {
112	            return "MINOR";
113	        }
114	        if (years < 65) {
115	            return "ADULT";
116	        }
117	        return "SENIOR";
118	    }
119	
120	    /**
121	     * The owner's preferred contact channel, derived at read time: {@code EMAIL}
122	     * when an email address is present, otherwise {@code PHONE}.
123	     */
124	    default String contactPreference(Owner owner) {
125	        if (owner == null) {
126	            return null;
127	        }
128	        String email = owner.getEmail();
129	        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
130	    }
131	
132	    /** Fixed city-to-region table used to derive an owner's locality at read time. */
133	    Map<String, String> CITY_REGION = Map.of(
134	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
135	
136	    /** Region to its inclusive 4-digit postcode range {low, high}. */
137	    Map<String, int[]> REGION_POSTCODES = Map.of(
138	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
139	
140	    /** Fixed region-to-timezone table, mapping each region to its IANA timezone name. */
141	    Map<String, String> REGION_TIMEZONE = Map.of(
142	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
143	
144	    /**
145	     * The owner's locality, derived at read time from the {@code memberId}: its leading REGION prefix
146	     * (the run of letters before the FY digits). That region was itself derived at write time from the
147	     * postcode (preferred) or city, defaulting to {@code UNKNOWN}, so reading it back keeps locality
148	     * and the member identity in lock-step.
149	     *
150	     * <p>Owners predating the unified {@code memberId} (e.g. seed data with no memberId) fall back to
151	     * the historical read-time derivation: postcode preferred, then city, then {@code UNKNOWN}.
152	     */
153	    default String locality(Owner owner) {
154	        if (owner == null) {
155	            return null;
156	        }
157	        String region = regionFromMemberId(owner.getMemberId());
158	        if (region != null) {
159	            return region;
160	        }
161	        String byPostcode = regionFromPostcode(owner.getPostcode());
162	        if (byPostcode != null) {
163	            return byPostcode;
164	        }
165	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
166	    }
167	
168	    /**
169	     * The leading REGION prefix of a {@code memberId}: its run of leading letters, which sits before
170	     * the two FY digits. Null when the {@code memberId} is absent or does not start with a letter.
171	     * Kept {@code private static} so MapStruct does not treat it as a property mapping method.
172	     */
173	    private static String regionFromMemberId(String memberId) {
174	        if (memberId == null || memberId.isEmpty()) {
175	            return null;
176	        }
177	        int i = 0;
178	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
179	            i++;
180	        }
181	        return i > 0 ? memberId.substring(0, i) : null;
182	    }
183	
184	    /**
185	     * The owner's segment, derived at read time and formatted {@code <TIER>_<AREA>}. TIER is
186	     * {@code PREMIUM} when the owner's {@code membershipLevel} is 3 or more, otherwise
187	     * {@code STANDARD}. AREA is {@code METRO} when the owner's {@link #locality(Owner) locality} is a
188	     * known region (NSW, VIC or QLD), otherwise {@code REGIONAL}. Null when the owner is absent.
189	     */
190	    default String ownerSegment(Owner owner) {
191	        if (owner == null) {
192	            return null;
193	        }
194	        Integer level = owner.getMembershipLevel();
195	        String tier = (level != null && level >= 3) ? "PREMIUM" : "STANDARD";
196	        String area = REGION_TIMEZONE.containsKey(locality(owner)) ? "METRO" : "REGIONAL";
197	        return tier + "_" + area;
198	    }
199	
200	    /**
201	     * The owner's IANA timezone, derived at read time from the owner's locality/region via the fixed
202	     * region-to-timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane).
203	     * Null when the owner is absent or the region has no known timezone (e.g. {@code UNKNOWN}), so the
204	     * field is simply omitted then.
205	     */
206	    default String timezone(Owner owner) {
207	        if (owner == null) {
208	            return null;
209	        }
210	        return REGION_TIMEZONE.get(locality(owner));
211	    }
212	
213	    /**
214	     * The region whose postcode range contains {@code postcode}, or {@code null} when the postcode is
215	     * absent, not four digits, or in no known range. Kept {@code private static} so MapStruct does not
216	     * treat it as a {@code String}-to-{@code String} property mapping method.
217	     */
218	    private static String regionFromPostcode(String postcode) {
219	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
220	            return null;
221	        }
222	        int value = Integer.parseInt(postcode);
223	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
224	            int[] range = entry.getValue();
225	            if (value >= range[0] && value <= range[1]) {
226	                return entry.getKey();
227	            }
228	        }
229	        return null;
230	    }
231	
232	    /** Known E.164 country codes, longest first so '61' matches before the shorter '1', mirroring
233	     *  the write-time normalization in NormalizeOwnerTelephone. */
234	    List<String> COUNTRY_CODES = List.of("61", "1");
235	
236	    /**
237	     * The stored E.164 {@code telephone} formatted for humans at read time: the country code, a single
238	     * space, then the national digits grouped in threes from the left, e.g. {@code '+61412345678'} ->
239	     * {@code '+61 412 345 678'}. The raw {@code telephone} is unchanged. Null when the owner is absent;
240	     * a value that is not a recognizable E.164 string (no leading {@code '+'}, non-digits, or no known
241	     * country code) is returned unchanged.
242	     */
243	    default String telephoneDisplay(Owner owner) {
244	        if (owner == null) {
245	            return null;
246	        }
247	        String telephone = owner.getTelephone();
248	        if (telephone == null || !telephone.startsWith("+")) {
249	            return telephone;
250	        }
251	        String digits = telephone.substring(1);
252	        if (!digits.matches("[0-9]+")) {
253	            return telephone;
254	        }
255	        String countryCode = null;
256	        for (String code : COUNTRY_CODES) {
257	            if (digits.startsWith(code)) {
258	                countryCode = code;
259	                break;
260	            }
261	        }
262	        if (countryCode == null) {
263	            return telephone;
264	        }
265	        String national = digits.substring(countryCode.length());
266	        StringBuilder grouped = new StringBuilder();
267	        for (int i = 0; i < national.length(); i++) {
268	            if (i > 0 && i % 3 == 0) {
269	                grouped.append(' ');
270	            }
271	            grouped.append(national.charAt(i));
272	        }
273	        return "+" + countryCode + (grouped.length() == 0 ? "" : " " + grouped);
274	    }
275	
276	    /**
277	     * The owner's salutation, derived at read time as the stored title and last name
278	     * separated by a single space (e.g. 'DR Franklin'), or just the last name when no
279	     * title was supplied (null or blank).
280	     */
281	    default String salutation(Owner owner) {
282	        if (owner == null) {
283	            return null;
284	        }
285	        String title = owner.getTitle();
286	        if (title == null || title.isBlank()) {
287	            return owner.getLastName();
288	        }
289	        return title + " " + owner.getLastName();
